function browserOpenUrl(baseUrl, openPath) {
  const base = baseUrl.endsWith("/") ? baseUrl : `${baseUrl}/`;
  const rel = String(openPath ?? "/").trim() || "/";
  if (rel === "/") return base;
  return new URL(rel.replace(/^\//, ""), base).href;
}
async function runShowReport(opts = {}) {
  const reportRoot = resolveReportRoot(opts);
  const host = opts.host ?? DEFAULT_SHOW_REPORT_HOST;
  const port = opts.port ?? DEFAULT_SHOW_REPORT_PORT;
  const openBrowser = opts.openBrowser !== false;
  let server;
  try {
    server = await startShowReportServer({ reportRoot, host, port });
  } catch (e) {
    const err = e;
    if (err?.code === "EADDRINUSE") {
      const url = browserOpenUrl(`http://${host}:${port}/`, opts.openPath);
      console.log(`[Merv] Port ${port} is already in use \u2014 a MERV server is likely running there.`);
      console.log(`[Merv] That server may be serving a DIFFERENT report folder than this one.`);
      console.log(`[Merv]   this folder: ${reportRoot}`);
      console.log(`[Merv] If the page looks empty or stale, stop the other process (Ctrl+C in its`);
      console.log(`[Merv] terminal) and re-run, or pick another port with --port.`);
      console.log(`[Merv] Opening ${url}`);
      if (openBrowser) openInBrowser(url);
      return;
    }
    throw e;
  }
  const openUrl = browserOpenUrl(server.url, opts.openPath);
  console.log(`[Merv] Serving local reports`);
  console.log(`[Merv]   folder: ${server.reportRoot}`);
  console.log(`[Merv]   url:    ${openUrl}`);
  console.log(`[Merv] Press Ctrl+C to stop.`);
  if (openBrowser) openInBrowser(openUrl);
  await new Promise((resolve) => {
    const stop = () => {
      void server.close().finally(() => resolve());
    };
    process.once("SIGINT", stop);
    process.once("SIGTERM", stop);
  });
}

